    /// <summary>
    /// UI and report text in English and Thai. The language is chosen in the Asset Gate window
    /// (stored in EditorPrefs); check results written to reports use the same language.
    /// </summary>
    public static class Lang
    {
        const string Pref = "ETLOLZ.AssetGate.Language";
        public const string Default = "en";

        public static readonly string[] Codes = { "en", "th" };
        public static readonly string[] Names = { "English", "ไทย" };

        public static string Current
        {
            get => EditorPrefs.GetString(Pref, Default) == "th" ? "th" : "en";
            set => EditorPrefs.SetString(Pref, value == "th" ? "th" : "en");
        }

        /// <summary>Translated text; {0}, {1}… are filled with string.Format.</summary>
        public static string T(string key, params object[] args)
        {
            var pair = Strings[key];
            var text = Current == "th" ? pair[1] : pair[0];
            return args.Length == 0 ? text : string.Format(text, args);
        }

